const tz = 'America/New_York';
const q = ($input.first().json.query) || {};
const mode = (q.mode || 'morning').toLowerCase();
const now = $now.setZone(tz);
const start = now.startOf('day');
const end = mode === 'friday' ? start.plus({ days: 8 }) : start.plus({ days: 1 });
return [{ json: { mode, timeMin: start.toISO(), timeMax: end.toISO(), generated_at: now.toISO() } }];

function errMsg(j) {
  const e = j && j.error;
  if (!e) return null;
  return typeof e === 'string' ? e : (e.message || JSON.stringify(e));
}
const body = $input.first().json;
const em = errMsg(body);
if (em) return [{ json: { kind: 'calendar', calendar_ok: false, error: em, calendar: null } }];
const items = Array.isArray(body.items) ? body.items : [];
const events = items
  .filter(e => (e.status || 'confirmed') !== 'cancelled')
  .map(e => ({
    id: e.id,
    summary: e.summary || '(no title)',
    start: (e.start && (e.start.dateTime || e.start.date)) || null,
    end: (e.end && (e.end.dateTime || e.end.date)) || null,
    all_day: !!(e.start && e.start.date && !e.start.dateTime)
  }));
return [{ json: { kind: 'calendar', calendar_ok: true, error: null, calendar: events } }];

function errMsg(j) {
  const e = j && j.error;
  if (!e) return null;
  return typeof e === 'string' ? e : (e.message || JSON.stringify(e));
}
const body = $input.first().json;
const em = errMsg(body);
if (em) return [{ json: { __state: 'error', __msg: em } }];
const msgs = Array.isArray(body.messages) ? body.messages : [];
if (msgs.length === 0) return [{ json: { __state: 'empty' } }];
return msgs.map(m => ({ json: { __state: 'ok', id: m.id } }));

function errMsg(j) {
  const e = j && j.error;
  if (!e) return null;
  return typeof e === 'string' ? e : (e.message || JSON.stringify(e));
}
function header(headers, name) {
  const h = (headers || []).find(x => (x.name || '').toLowerCase() === name);
  return h ? h.value : null;
}
const items = $input.all();
if (items.length === 1 && items[0].json.__state === 'error') {
  return [{ json: { kind: 'mail', mail_ok: false, error: items[0].json.__msg, mail_needing_reply: null } }];
}
if (items.length === 1 && items[0].json.__state === 'empty') {
  return [{ json: { kind: 'mail', mail_ok: true, error: null, mail_needing_reply: [] } }];
}
const failed = items.find(it => errMsg(it.json));
if (failed) return [{ json: { kind: 'mail', mail_ok: false, error: 'metadata fetch failed: ' + errMsg(failed.json), mail_needing_reply: null } }];
const mail = items.map(it => {
  const j = it.json;
  const headers = (j.payload && j.payload.headers) || [];
  return {
    id: j.id,
    from: header(headers, 'from'),
    subject: header(headers, 'subject'),
    date: header(headers, 'date'),
    snippet: j.snippet || null
  };
});
return [{ json: { kind: 'mail', mail_ok: true, error: null, mail_needing_reply: mail } }];

const items = $input.all();
const cal = items.find(it => it.json.kind === 'calendar');
const mail = items.find(it => it.json.kind === 'mail');
const range = $('Compute range').first().json;
return [{ json: {
  mode: range.mode,
  range: { timeMin: range.timeMin, timeMax: range.timeMax },
  generated_at: range.generated_at,
  calendar_ok: cal ? cal.json.calendar_ok : false,
  calendar: cal ? cal.json.calendar : null,
  calendar_error: cal ? cal.json.error : 'calendar branch did not run',
  mail_ok: mail ? mail.json.mail_ok : false,
  mail_needing_reply: mail ? mail.json.mail_needing_reply : null,
  mail_error: mail ? mail.json.error : 'mail branch did not run'
} }];
